                          ? `${transcript.activeFindMatchIndex + 1}/${transcript.findMatchCount}`
                          : `0/${transcript.findMatchCount}`}
                      </span>
                      <button
                        type="button"
                        onClick={() => transcript.moveFindMatch(-1)}
