                            modals.mediaPlayerRef.current = node
                          }}
                          src={modals.embeddedMediaUrl}
                          controls
                          preload="metadata"
                          className="w-full rounded"
                          data-testid="embedded-video-player"
                        />
                      ) : (
                        <audio
                          ref={(node) => {
                            modals.mediaPlayerRef.current = node
                          }}
                          src={modals.embeddedMediaUrl}
                          controls
                          preload="metadata"
                          className="w-full"
                          data-testid="embedded-audio-player"
                        />
                      )
